import time

def retry_with_backoff(fn, max_attempts=3):
    """Call `fn` at most `max_attempts` times, returning its result on success.
    If all attempts fail, the last exception is re‑raised without a trailing
    sleep."""
    attempt = 1  # First attempt
    while attempt <= max_attempts:
        try:
            return fn()
        except Exception as e:
            if attempt == max_attempts:
                # Last attempt failed – re‑raise without sleeping
                raise
            # Wait before retrying
            time.sleep(0.01 * attempt)
            attempt += 1
