def find_rotation_point(arr):
    """Index of the smallest element in a rotated sorted array."""
    if not arr:
        return -1

    lo, hi = 0, len(arr) - 1

    # If the array is not rotated (first element is <= last element),
    # the smallest element is at index 0.
    if arr[lo] <= arr[hi]:
        return 0

    while lo < hi:
        mid = (lo + hi) // 2
        # If the middle element is greater than the last element,
        # the rotation point is to the right of mid.
        if arr[mid] > arr[hi]:
            lo = mid + 1
        else:
            hi = mid
    return lo
```

