def merge_sorted(a, b):
    """Merge two sorted (ascending) lists into one sorted list."""
    i = j = 0
    out = []

    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1

    # Append any remaining elements from the longer list
    if i < len(a):
        out.extend(a[i:])
    elif j < len(b):
        out.extend(b[j:])

    return out
